A=(secs('15:18:55'),secs('15:19:40')); B=(secs('15:20:05'),secs('15:21:35')); C=(secs('15:22:00'),secs('15:22:40'))
def w(r): return df[(df.bucket_start_s>=r[0])&(df.bucket_start_s<r[1])]
# accept4 / connect full per-container table
for e in ['syscall_entry_accept4','syscall_entry_connect','syscall_entry_recvfrom','syscall_entry_sendto','syscall_entry_epoll_pwait']:
    print("=====",e)
    tab={}
    for nm,r in [('A',A),('B',B),('C',C)]:
        d=w(r); dur=r[1]-r[0]; d=d[d.event==e]
        for ns,v in d.groupby('pid_ns').n.sum().items():
            tab.setdefault(str(ns),{})[nm]=v/dur
    for ns,v in sorted(tab.items(), key=lambda kv:-kv[1].get('A',0))[:8]:
        print(f"   ns {ns}: A={v.get('A',0):8.1f} B={v.get('B',0):8.1f} C={v.get('C',0):8.1f}  B/A={v.get('B',0)/v['A'] if v.get('A') else float('nan'):.2f}")

