import re
# 1. block latency from raw lines
for lab,t0,t1 in [('quiet','15:19:10','15:19:20'),('window','15:20:30','15:20:40')]:
    iss=get_lines('block_rq_issue',secs(t0),secs(t1),limit=400)
    cmp_=get_lines('block_rq_complete',secs(t0),secs(t1),limit=400)
    def parse(ls):
        out=[]
        for l in ls:
            m=re.match(r'\[(\d+):(\d+):([\d.]+)\]',l)
            s=re.search(r'sector = (\d+)',l); n=re.search(r'nr_sector = (\d+)',l)
            if m and s: out.append((int(m.group(1))*3600+int(m.group(2))*60+float(m.group(3)), int(s.group(1))))
        return out
    I=parse(iss); C=parse(cmp_)
    cm={}
    for t,s in C: cm.setdefault(s,[]).append(t)
    lat=[]
    for t,s in I:
        for tc in cm.get(s,[]):
            if tc>=t: lat.append((tc-t)*1000); break
    lat.sort()
    if lat: print(f"block issue->complete {lab}: n={len(lat)} p50={lat[len(lat)//2]:.3f}ms p95={lat[int(len(lat)*.95)]:.3f}ms max={lat[-1]:.2f}ms")
    else: print(lab,"no matched pairs", len(I), len(C))
